import{_ as e,o as p,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"props传递","description":"在 Vue 3 的 \\\\<script setup\\\\ 中，直接传递 props.unit 是否能保持响应性取决于子组件如何处理它。以下是具体分析和解决方案： 1. 直接传递 props.unit 的响应性问题 父组件传递的是 computed 的解包值（如 currency.val。","frontmatter":{"title":"props传递","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"在 Vue 3 的 \\\\<script setup\\\\ 中，直接传递 props.unit 是否能保持响应性取决于子组件如何处理它。以下是具体分析和解决方案： 1. 直接传递 props.unit 的响应性问题 父组件传递的是 computed 的解包值（如 currency.val。","sidebarWeight":145,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/响应式问题/props传递.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/props传递.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/props传递.md"}'),s={name:"posts/Vue系统教程/03-响应式与组合式 API/props传递.md"};function u(i,t,n,d,a,c){return p(),o("div",null,[...t[0]||(t[0]=[r('<div><h1 id="props传递" tabindex="-1">props传递 <a class="header-anchor" href="#props传递" aria-label="Permalink to &quot;props传递&quot;">​</a></h1><blockquote><p>本节目标：理解“props传递”的核心思路，并能把它用于实际开发或面试表达。 在 Vue 3 的 ==&lt;script setup&gt;== 中，直接传递 ==props.unit== 是否能保持响应性取决于子组件如何处理它。以下是具体分析和解决方案：</p></blockquote><p>==1. 直接传递== ==props.unit== ==的响应性问题==</p><ul><li>==父组件传递的是== ==computed== ==的解包值（如== ==currency.value====），子组件通过== ==props.unit== ==接收时：========vue========复制========下载========&lt;!-- 父组件 --&gt;========&lt;DataItemVue== ==:unit=====&quot;====currency====&quot; /&gt;== ==&lt;!-- currency 是 computed --&gt;============&lt;!-- 子组件接收到的实际是 currency.value（字符串，非响应式） --&gt;==</li><li>==结果：========如果== ==currency== ==变化，子组件的== ==props.unit== ==不会自动更新，因为它已经是静态值。== ==2. 如何保持响应性？== ==方法 1：子组件用== ==toRef== ==包装 props== ==在子组件中将== ==props.unit== ==转为== ==ref====，以保持对父级变化的响应：== typescript 复制 下载 // 子组件 (DataItemVue)import { toRef } from &#39;vue&#39;; const props = defineProps&lt;{ unit: string; // 父组件传递的是解包后的值}&gt;(); // 将 props.unit 转为响应式引用const unitRef = toRef(props, &#39;unit&#39;); // 传递给孙组件时，直接传递 unitRef（响应式）&lt;GrandChildComponent :unit=&quot;unitRef&quot; /&gt; ==原理：== ==toRef(props, &#39;unit&#39;)== ==会创建一个与父组件== ==unit== ==源保持同步的== ==ref====，即使父组件重新渲染传递新值，====unitRef== ==也会更新。==</li></ul><p>==方法 2：父组件传递整个== ==computed== ==对象== ==修改父组件，直接传递== ==computed== ==而非其值：== vue 复制 下载 &lt;!-- 父组件 --&gt;&lt;DataItemVue :unit=&quot;currency&quot; /&gt; &lt;!-- currency 是 computed 对象 --&gt; &lt;!-- 子组件声明 props 时接受 ComputedRef --&gt;&lt;script setup lang=&quot;ts&quot;&gt;const props = defineProps&lt;{ unit: string | ComputedRef&lt;string&gt;; // 明确允许 ComputedRef}&gt;();&lt;/script&gt; ==优点：== ==子组件可以直接使用== ==props.unit====（无需== ==toRef====），因为它本身就是响应式的。==</p><p>==3. 关键对比==</p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td>方法</td><td>是否需要修改父组件</td><td>子组件处理方式</td><td>响应性保证</td></tr><tr><td>直接传递 ==props.unit==</td><td>❌ 否</td><td>需用 ==toRef(props, &#39;unit&#39;)==</td><td>✅ 可靠</td></tr><tr><td>传递 ==computed== 对象</td><td>✅ 是</td><td>直接使用 ==props.unit==</td><td>✅ 更直接</td></tr></tbody></table><p>==4. 代码示例（方法 1：子组件处理）== ==子组件 (====DataItemVue====)== typescript 复制 下载 import { toRef } from &#39;vue&#39;; const props = defineProps&lt;{ unit: string; // 父组件传递的是解包后的值}&gt;(); // 转为响应式const unitRef = toRef(props, &#39;unit&#39;); // 传递给孙组件&lt;GrandChildComponent :unit=&quot;unitRef&quot; /&gt; ==孙组件 (====GrandChildComponent====)== ==直接使用== ==unit== ==prop，它会随父组件的== ==currency== ==变化自动更新：== typescript 复制 下载 const props = defineProps&lt;{ unit: string; // 实际接收的是响应式 unitRef}&gt;();</p><p>==5. 注意事项==</p><ul><li><p>==toRef== ==vs== ==computed==</p></li><li><p>==toRef(props, &#39;unit&#39;)====：适用于 props 是静态值但需响应父级更新。==</p></li><li><p>==computed(() =&gt; props.unit)====：适用于需要派生逻辑的场景（如格式化）。==</p></li><li><p>==TypeScript 类型========如果父组件可能传递== ==computed== ==或普通值，子组件 props 类型应声明为联合类型：========typescript========复制========下载========defineProps====&lt;===={====== ==unit====:== ==string== ==|== ==ComputedRef====&lt;====string====&gt;====;========}====&gt;====();== ==总结==</p></li><li><p>==直接传递== ==props.unit== ==到孙组件：需在子组件中用== ==toRef== ==包装以保持响应性。==</p></li><li><p>==最佳实践：==</p></li><li><p>==如果可控父组件，优先传递== ==computed== ==对象（====&lt;Child :unit=&quot;computedValue&quot; /&gt;====）。==</p></li><li><p>==否则，在子组件中用== ==toRef(props, &#39;unit&#39;)== ==转为响应式引用再传递。==</p></li></ul><p>这样可以确保 ==unit== 的响应性在整个组件链中完整传递。 &gt; 来自 &lt;<a href="https://chat.deepseek.com/a/chat/s/b75a0d7c-399b-41a3-9de9-567fc7280f28" target="_blank" rel="noreferrer">https://chat.deepseek.com/a/chat/s/b75a0d7c-399b-41a3-9de9-567fc7280f28</a>&gt;</p><p>&gt; 来自 &lt;<a href="https://chat.deepseek.com/a/chat/s/b75a0d7c-399b-41a3-9de9-567fc7280f28" target="_blank" rel="noreferrer">https://chat.deepseek.com/a/chat/s/b75a0d7c-399b-41a3-9de9-567fc7280f28</a>&gt;</p></div>',1)])])}const m=e(s,[["render",u]]);export{f as __pageData,m as default};
